import Foundation

public final class CacheService: Sendable {
    public static let shared = CacheService()
    
    private init() {}
    
    private var searchDirectories: [URL] {
        var dirs = [FileManager.default.temporaryDirectory]
        let tmpDir = URL(fileURLWithPath: "/private/tmp")
        if FileManager.default.fileExists(atPath: tmpDir.path) {
            dirs.append(tmpDir)
        }
        return dirs
    }
    
    /// Calculate current temporary cache size generated by BenchmarkAnimator / Visualized Benchmark
    public func calculateCacheSize() -> Int64 {
        var total: Int64 = 0
        for dir in searchDirectories {
            guard let files = try? FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: [.fileSizeKey]) else {
                continue
            }
            for file in files {
                let name = file.lastPathComponent
                if isBenchmarkCacheFile(name) {
                    if let size = (try? file.resourceValues(forKeys: [.fileSizeKey]))?.fileSize {
                        total += Int64(size)
                    }
                }
            }
        }
        return total
    }
    
    /// Format bytes into human readable string (e.g. "12.4 MB")
    public func formatBytes(_ bytes: Int64) -> String {
        let b = Double(bytes)
        if b >= 1024 * 1024 * 1024 {
            return String(format: "%.2f GB", b / (1024 * 1024 * 1024))
        } else if b >= 1024 * 1024 {
            return String(format: "%.1f MB", b / (1024 * 1024))
        } else if b >= 1024 {
            return String(format: "%.1f KB", b / 1024)
        } else {
            return "\(bytes) Bytes"
        }
    }
    
    /// Clear benchmark temporary cache and return freed bytes
    public func clearCache() -> (freedBytes: Int64, message: String) {
        var freed: Int64 = 0
        var count = 0
        
        for dir in searchDirectories {
            guard let files = try? FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: [.fileSizeKey]) else {
                continue
            }
            for file in files {
                let name = file.lastPathComponent
                if isBenchmarkCacheFile(name) {
                    if let size = (try? file.resourceValues(forKeys: [.fileSizeKey]))?.fileSize {
                        freed += Int64(size)
                    }
                    try? FileManager.default.removeItem(at: file)
                    count += 1
                }
            }
        }
        
        if count > 0 {
            return (freed, "已成功清除 \(count) 個暫存檔案，釋放 \(formatBytes(freed)) 空間！")
        } else {
            return (0, "暫存快取已是最新狀態，無需清除。")
        }
    }
    
    private func isBenchmarkCacheFile(_ name: String) -> Bool {
        name.hasPrefix("test_benchmark_") ||
        name.hasPrefix("export_") ||
        name.hasPrefix("benchmark_") ||
        name.contains("BenchmarkAnimator") ||
        name.contains("Visualized") ||
        name.hasPrefix("dmg_staging") ||
        name == "AppIcon.iconset" ||
        name.hasPrefix("icon_scale_") ||
        name == "visualized_benchmark_icon.png" ||
        (name.hasSuffix(".mov") && name.contains("test")) ||
        (name.hasSuffix(".mp4") && name.contains("test")) ||
        (name.hasSuffix(".png") && name.contains("test"))
    }
}
